    select A.*,M.MACHINE_NAME from t_tc_quota_setting A LEFT JOIN T_TC_MACHINE_INFO M
    ON A.machine_id=M.ID
    WHERE A.del_flag='0'
    and A.sidewall_code = #{sidewallCode}
    and A.machine_id = #{machineId}

        order by A.create_time desc

) t

    order by ${orderStr}

